const COURSE_LESSON_HTML = {
  "kurssArticlesLesson": "\n  <h3>Artikeliai</h3>\n\n  <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Vokiešu artikelis ne visada sutampa su lietuviška gimine. Todėl daiktavardžius geriausia mokytis kartu su artikeliu.</div>\n  </div>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Artikelių pavyzdžiai</h4>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Tisch — stalas</div>\n      <div class=\"kurss-example\">die Tür — durys</div>\n      <div class=\"kurss-example\">das Messer — peilis</div>\n      <div class=\"kurss-example\">das Mädchen — mergaitė</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♂</span>Dažnai DER</h4>\n    <p class=\"artikuli-explain\">DER dažnai būna vyriškos giminės asmenys, dienos, mėnesiai, metų laikai ir keli žodžiai su tam tikromis galūnėmis.</p>\n\n    <h5 class=\"artikuli-subtitle\">Taisyklės</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-er → dažnai DER, pavyzdžiui: der Computer, der Lehrer <span class=\"artikuli-note\">bet ne visada</span></div>\n      <div class=\"kurss-example\">-ling → dažnai DER, pavyzdžiui: der Schmetterling</div>\n      <div class=\"kurss-example\">-ismus → dažnai DER, pavyzdžiui: der Tourismus, der Kapitalismus</div>\n      <div class=\"kurss-example\">vyriškos giminės asmenys → der Mann, der Vater</div>\n      <div class=\"kurss-example\">profesijos → der Lehrer, der Arzt</div>\n      <div class=\"kurss-example\">automobilių markės → der BMW, der Mercedes</div>\n      <div class=\"kurss-example\">dienos → der Montag, der Dienstag</div>\n      <div class=\"kurss-example\">mėnesiai → der August, der Dezember</div>\n      <div class=\"kurss-example\">metų laikai → der Sommer, der Winter</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Pavyzdžiai</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Mann — vyras</div>\n      <div class=\"kurss-example\">der Vater — tėvas</div>\n      <div class=\"kurss-example\">der Montag — pirmadienis</div>\n      <div class=\"kurss-example\">der August — rugpjūtis</div>\n      <div class=\"kurss-example\">der Sommer — vasara</div>\n      <div class=\"kurss-example\">der Lehrer — mokytojas</div>\n      <div class=\"kurss-example\">der Computer — kompiuteris</div>\n      <div class=\"kurss-example\">der Schmetterling — peteliškė</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♀</span>Dažnai DIE</h4>\n    <p class=\"artikuli-explain\">DIE dažnai būna moteriškos giminės asmenys, daugiskaita ir žodžiai su galūnėmis -ung, -heit, -keit, -schaft, -ion, -tät, -ei.</p>\n\n    <h5 class=\"artikuli-subtitle\">Taisyklės</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-ung → die Wohnung, die Rechnung</div>\n      <div class=\"kurss-example\">-heit → die Freiheit, die Gesundheit</div>\n      <div class=\"kurss-example\">-keit → die Möglichkeit</div>\n      <div class=\"kurss-example\">-schaft → die Mannschaft</div>\n      <div class=\"kurss-example\">-ion → die Nation</div>\n      <div class=\"kurss-example\">-tät → die Universität</div>\n      <div class=\"kurss-example\">-ei → die Polizei, die Bäckerei</div>\n      <div class=\"kurss-example\">moteriškos giminės asmenys → die Frau, die Mutter</div>\n      <div class=\"kurss-example\">motociklų markės → die Harley-Davidson, die Yamaha</div>\n      <div class=\"kurss-example\">daugiskaita → die Autos, die Häuser</div>\n      <div class=\"kurss-example\">daugiskaita beveik visada → die Autos, die Häuser, die Kinder</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Pavyzdžiai</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Frau — moteris</div>\n      <div class=\"kurss-example\">die Mutter — motina</div>\n      <div class=\"kurss-example\">die Wohnung — butas</div>\n      <div class=\"kurss-example\">die Rechnung — sąskaita</div>\n      <div class=\"kurss-example\">die Freiheit — laisvė</div>\n      <div class=\"kurss-example\">die Möglichkeit — galimybė</div>\n      <div class=\"kurss-example\">die Mannschaft — komanda</div>\n      <div class=\"kurss-example\">die Nation — tauta</div>\n      <div class=\"kurss-example\">die Universität — universitetas</div>\n      <div class=\"kurss-example\">die Polizei — policija</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>◇</span>Dažnai DAS</h4>\n    <p class=\"artikuli-explain\">DAS dažnai būna mažybiniai žodžiai su -chen / -lein, daugelis žodžių su -ment / -um ir veiksmažodžiai, vartojami kaip daiktavardžiai.</p>\n\n    <h5 class=\"artikuli-subtitle\">Taisyklės</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-chen → das Mädchen, das Häuschen</div>\n      <div class=\"kurss-example\">-lein → das Fräulein</div>\n      <div class=\"kurss-example\">-ment → das Instrument</div>\n      <div class=\"kurss-example\">-um → das Zentrum, das Museum</div>\n      <div class=\"kurss-example\">metalai → das Gold, das Silber, das Eisen</div>\n      <div class=\"kurss-example\">chemijos elementai → das Eisen, das Sauerstoff</div>\n      <div class=\"kurss-example\">viešbučiai → das Hotel</div>\n      <div class=\"kurss-example\">spalvos kaip daiktavardžiai → das Rot, das Blau</div>\n      <div class=\"kurss-example\">veiksmažodis kaip daiktavardis → das Essen, das Lernen</div>\n      <div class=\"kurss-example\">veiksmažodžiai kaip daiktavardžiai → das Essen, das Lernen, das Lesen</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Pavyzdžiai</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">das Kind — vaikas</div>\n      <div class=\"kurss-example\">das Mädchen — mergaitė</div>\n      <div class=\"kurss-example\">das Häuschen — namelis</div>\n      <div class=\"kurss-example\">das Instrument — instrumentas</div>\n      <div class=\"kurss-example\">das Zentrum — centras</div>\n      <div class=\"kurss-example\">das Museum — muziejus</div>\n      <div class=\"kurss-example\">das Essen — valgymas / maistas</div>\n      <div class=\"kurss-example\">das Lernen — mokymasis</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>!</span>Svarbios išimtys / reikia mokytis su artikeliu</h4>\n    <p class=\"artikuli-explain\">Kai kuriems žodžiams artikelio pagal galūnę ar lietuvišką giminę patikimai nustatyti negalima. Juos geriausia mokytis kartu su artikeliu.</p>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Tür — durys</div>\n      <div class=\"kurss-example\">das Messer — peilis</div>\n      <div class=\"kurss-example\">die Sonne — saulė</div>\n      <div class=\"kurss-example\">der Mond — mėnulis</div>\n      <div class=\"kurss-example\">das Mädchen — mergaitė</div>\n      <div class=\"kurss-example\">das Auto — automobilis</div>\n      <div class=\"kurss-example\">der Käse — sūris</div>\n      <div class=\"kurss-example\">die Gabel — šakutė</div>\n    </div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Galūnės ir žodžių grupės padeda atspėti artikelį, tačiau tai nėra 100% patikima taisyklė. Jei nesi tikras, mokykis žodžio kartu su artikeliu.</div>\n  </div>\n",
  "kurssPronounsLesson": "\n  <h3>Įvardžiai</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativ, Akkusativ ir Dativ — įvardžių formos.</div>\n  </div>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>N</span>Nominativ — kas?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich — aš</div><div class=\"kurss-example\">du — tu</div><div class=\"kurss-example\">er — jis</div><div class=\"kurss-example\">sie — ji</div><div class=\"kurss-example\">es — tai</div><div class=\"kurss-example\">wir — mes</div><div class=\"kurss-example\">ihr — jūs</div><div class=\"kurss-example\">sie — jie / jos</div><div class=\"kurss-example\">Sie — Jūs (mandagumo forma)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>A</span>Akkusativ — ką?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mich — mane</div><div class=\"kurss-example\">dich — tave</div><div class=\"kurss-example\">ihn — jį (vyr.)</div><div class=\"kurss-example\">sie — ją (mot.)</div><div class=\"kurss-example\">es — tai</div><div class=\"kurss-example\">uns — mus</div><div class=\"kurss-example\">euch — jus</div><div class=\"kurss-example\">sie — juos / jas</div><div class=\"kurss-example\">Sie — Jūs (mandagumo forma)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>D</span>Dativ — kam?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mir — man</div><div class=\"kurss-example\">dir — tau</div><div class=\"kurss-example\">ihm — jam / tam</div><div class=\"kurss-example\">ihr — jai</div><div class=\"kurss-example\">uns — mums</div><div class=\"kurss-example\">euch — jums</div><div class=\"kurss-example\">ihnen — jiems / joms</div><div class=\"kurss-example\">Ihnen — Jums (mandagumo forma)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>?</span>Kaip pasirinkti formą?</h4>\n    <ul class=\"kurss-summary-list\"><li><span class=\"case-blue\">Nominativ</span> — sakinio veiksnys (kas daro?)</li><li><span class=\"case-red\">Akkusativ</span> — tiesioginis objektas (ką?)</li><li><span class=\"case-green\">Dativ</span> — netiesioginis objektas (kam?)</li></ul>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Pavyzdžiai</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">dich</span>. — Aš tave matau.</div><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">ihn</span>. — Aš jį matau.</div><div class=\"kurss-example\">Wir mögen <span class=\"case-red\">euch</span>. — Mums jūs patinkate.</div><div class=\"kurss-example\">Ich helfe <span class=\"case-green\">dir</span>. — Aš tau padedu.</div><div class=\"kurss-example\">Ich gebe <span class=\"case-green\">ihm</span> ein Buch. — Aš duodu jam knygą.</div><div class=\"kurss-example\">Wir danken <span class=\"case-green\">euch</span>. — Mes jums dėkojame.</div></div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativ visada yra sakinio veiksnys, o Akkusativ ir Dativ — objektai. Žiūrėk į veiksmažodį ir klausk: <span class=\"case-red\">ką?</span> arba <span class=\"case-green\">kam?</span></div>\n  </div>\n",
  "kurssPronunciationLesson": "\n            <h3>Balsiai — ilgi ir trumpi</h3>\n            <p class=\"kurss-lesson-intro\">Vokiečių kalboje balsiai gali būti ilgi arba trumpi. Tai turi įtakos žodžio tarimui.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Ilgas balsis</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">warm (varm) — šiltas</div><div class=\"kurss-example\">gut (gūt) — geras</div><div class=\"kurss-example\">Tat (tāt) — darbas / veiksmas</div><div class=\"kurss-example\">Flur (flūr) — koridorius</div><div class=\"kurss-example\">Weg (vēk) — kelias</div><div class=\"kurss-example\">Hut (hūt) — kepurė</div><div class=\"kurss-example\">Hof (hōf) — kiemas</div><div class=\"kurss-example\">Schlaf (šlāf) — miegas</div></div>\n              <p>Jei po balsio seka vienas priebalsis, balsis dažnai tariamas ilgai.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Trumpas balsis</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Pilz (pilc) — grybas</div><div class=\"kurss-example\">Wort (vort) — žodis</div><div class=\"kurss-example\">Mund (munt) — burna</div><div class=\"kurss-example\">bald (balt) — greitai</div><div class=\"kurss-example\">scharf (šarf) — aštrus</div><div class=\"kurss-example\">Feld (felt) — laukas</div><div class=\"kurss-example\">voll (fol) — pilnas</div></div>\n              <p>Jei po balsio seka du ar daugiau priebalsių, balsis dažnai tariamas trumpai.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Galūnės en / el / er</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">singen (zingen) — dainuoti</div><div class=\"kurss-example\">tragen (trāgen) — nešti</div><div class=\"kurss-example\">Garten (garten) — sodas</div><div class=\"kurss-example\">Vogel (fogel) — paukštis</div><div class=\"kurss-example\">Segel (zēgel) — burė</div><div class=\"kurss-example\">Braten (brāten) — kepsnys</div><div class=\"kurss-example\">Bogen (bōgen) — lankas</div><div class=\"kurss-example\">Spiegel (špīgel) — veidrodis</div><div class=\"kurss-example\">Finger (finger) — pirštas</div><div class=\"kurss-example\">Halter (halter) — laikiklis</div><div class=\"kurss-example\">Arbeiter (arbaiter) — darbininkas</div><div class=\"kurss-example\">Häuser (hoizer) — namai</div><div class=\"kurss-example\">wieder (vīder) — vėl</div><div class=\"kurss-example\">breiter (braiter) — platesnis</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Raidė h kaip ilgumo ženklas</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Rahmen (rāmen) — rėmas</div><div class=\"kurss-example\">Ohr (ōr) — ausis</div><div class=\"kurss-example\">Kohle (kōle) — anglys</div><div class=\"kurss-example\">Zahl (cāl) — skaičius</div><div class=\"kurss-example\">ihn (īn) — jį</div><div class=\"kurss-example\">ihm (īm) — jam</div><div class=\"kurss-example\">Huhn (hūn) — višta</div><div class=\"kurss-example\">nahm (nām) — ėmė</div><div class=\"kurss-example\">nehmen (nēmen) — imti</div><div class=\"kurss-example\">Schuh (šū) — batas</div></div>\n              <p>Kai kuriuose žodžiuose h pailgina prieš tai esantį balsį. Tokiais atvejais h dažniausiai netariama.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Galūnės su e</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Lampe (lampe) — lempa</div><div class=\"kurss-example\">Hase (hāze) — zuikis</div><div class=\"kurss-example\">Knabe (knābe) — berniukas</div><div class=\"kurss-example\">Rabe (rābe) — kranklys</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Ilgasis i = ie</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">die (dī) — artikelis „die“</div><div class=\"kurss-example\">diese (dīze) — ši / šie</div><div class=\"kurss-example\">wieder (vīder) — vėl</div><div class=\"kurss-example\">Fliege (flīge) — musė</div><div class=\"kurss-example\">Ziege (cīge) — ožka</div><div class=\"kurss-example\">Stiel (štīl) — kotas</div><div class=\"kurss-example\">Dieb (dīp) — vagis</div><div class=\"kurss-example\">hier (hīr) — čia</div></div>\n              <p>Ilgasis i vokiečių kalboje dažnai rašomas kaip ie.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Dvigubi balsiai</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Saal (zāl) — salė</div><div class=\"kurss-example\">Saat (zāt) — sėja</div><div class=\"kurss-example\">Staat (štāt) — valstybė</div><div class=\"kurss-example\">Beere (bēre) — uoga</div><div class=\"kurss-example\">See (zē) — ežeras / jūra</div><div class=\"kurss-example\">Beet (bēt) — lysvė</div><div class=\"kurss-example\">Boot (bōt) — valtis</div><div class=\"kurss-example\">Moor (mōr) — pelkė</div><div class=\"kurss-example\">Moos (mōs) — samanos</div></div>\n              <p>Dvigubi balsiai dažniausiai tariami ilgai.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ä</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Wand (vant) — siena</div><div class=\"kurss-example\">Wände (vende) — sienos</div><div class=\"kurss-example\">Vater (fāter) — tėvas</div><div class=\"kurss-example\">Väter (fēter) — tėvai</div><div class=\"kurss-example\">Schrank (šrank) — spinta</div><div class=\"kurss-example\">Schränke (šrenke) — spintos</div><div class=\"kurss-example\">Bank (bank) — suolas / bankas</div><div class=\"kurss-example\">Bänke (benke) — suolai</div><div class=\"kurss-example\">Tal (tāl) — slėnis</div><div class=\"kurss-example\">Täler (tēler) — slėniai</div></div>\n              <p>ä yra a umliautas.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ö</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Rose (rōze) — rožė</div><div class=\"kurss-example\">Röschen (rēschen) — rožytė</div><div class=\"kurss-example\">Ofen (ōfen) — krosnis</div><div class=\"kurss-example\">Öfen (ēfen) — krosnys</div><div class=\"kurss-example\">Rock (rok) — sijonas</div><div class=\"kurss-example\">Röcke (röke) — sijonai</div></div>\n              <p>ö yra o umliautas.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ü</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">kurz (kurc) — trumpas</div><div class=\"kurss-example\">kürzer (kurcer) — trumpesnis</div><div class=\"kurss-example\">Kunst (kunst) — menas</div><div class=\"kurss-example\">Künste (künste) — menai</div><div class=\"kurss-example\">Mutter (muter) — motina</div><div class=\"kurss-example\">Mütter (mutter) — motinos</div></div>\n              <p>ü yra u umliautas.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Dvibalsiai: äu</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Baum (baum) — medis</div><div class=\"kurss-example\">Bäume (boime) — medžiai</div><div class=\"kurss-example\">Haus (haus) — namas</div><div class=\"kurss-example\">Häuser (hoizer) — namai</div><div class=\"kurss-example\">Strauch (štrauh) — krūmas</div><div class=\"kurss-example\">Sträucher (štroiher) — krūmai</div><div class=\"kurss-example\">Maus (maus) — pelė</div><div class=\"kurss-example\">Mäuse (moize) — pelės</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Dvibalsiai: eu</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">heute (hoite) — šiandien</div><div class=\"kurss-example\">Leute (loite) — žmonės</div><div class=\"kurss-example\">neu (noi) — naujas</div><div class=\"kurss-example\">neun (noin) — devyni</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Dvibalsiai: ei</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">mein (main) — mano</div><div class=\"kurss-example\">dein (dain) — tavo</div><div class=\"kurss-example\">sein (zain) — jo / jos / būti</div><div class=\"kurss-example\">frei (frai) — laisvas</div><div class=\"kurss-example\">arbeiten (arbaiten) — dirbti</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>2 pamokos tarimo pastabos</h4>\n              <ul class=\"kurss-summary-list\"><li>žodžiuose ich, nicht, rechnen, zeichnen „ch“ tariamas švelniai</li><li>žodžiuose arbeiten ir zeichnen „ei“ tariamas kaip „ai“</li><li>„sp“ žodžio pradžioje tariamas kaip „šp“</li><li>veiksmažodyje tun raidė „u“ tariama ilgai</li></ul>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Apibendrinimas</h4>\n              <ul class=\"kurss-summary-list\"><li>vienas priebalsis po balsio → dažnai ilgas balsis</li><li>du ar daugiau priebalsių → dažnai trumpas balsis</li><li>h gali pailginti balsį</li><li>ie dažnai reiškia ilgą i</li><li>dubliuoti balsiai dažniausiai yra ilgi</li></ul>\n            </section>\n",
  "kurssConsonantsLesson": "\n            <h3>Priebalsiai ir raidžių junginiai</h3>\n            <p class=\"kurss-lesson-intro\">Vokiečių kalboje kai kurie priebalsiai ir raidžių junginiai tariami kitaip, nei rašomi. Šioje pamokoje pateikti svarbiausi pavyzdžiai pradedantiesiems.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Priebalsiai</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">das Rad (rāt) — ratas</div><div class=\"kurss-example\">die Räder (rēder) — ratai</div><div class=\"kurss-example\">Bad (bāt) — vonia</div><div class=\"kurss-example\">Bäder (bēder) — vonios</div></div>\n              <p>Žodžio gale priebalsiai dažnai netariami taip, kaip rašomi.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ch</h4>\n              <p>„ch“ gali būti tariamas švelniai arba kietai. Kai kuriuose žodžiuose jis skamba kaip „h“, kituose — arčiau „k“.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">rechnen (rehnen) — skaičiuoti</div><div class=\"kurss-example\">zeichnen (caihnen) — piešti</div><div class=\"kurss-example\">nicht (niht) — ne</div><div class=\"kurss-example\">schlecht (šleht) — blogai</div><div class=\"kurss-example\">mich (mih) — mane</div><div class=\"kurss-example\">dich (dih) — tave</div><div class=\"kurss-example\">Strauch (štrauh) — krūmas</div><div class=\"kurss-example\">noch (noh) — vėl</div><div class=\"kurss-example\">Nacht (naht) — naktis</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>sch</h4>\n              <p>„sch“ vokiečių kalboje tariamas kaip lietuvių „š“.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Schule (šūle) — mokykla</div><div class=\"kurss-example\">Schüler (šūler) — mokinys</div><div class=\"kurss-example\">Schiff (šif) — laivas</div><div class=\"kurss-example\">Schraube (šraube) — varžtas</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>sp ir st žodžio pradžioje</h4>\n              <p>Žodžio ar skiemens pradžioje „sp“ dažnai tariamas kaip „šp“, o „st“ — kaip „št“.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">spielen (špīlen) — žaisti</div><div class=\"kurss-example\">Sprung (šprung) — šuolis</div><div class=\"kurss-example\">stehen (štēen) — stovėti</div><div class=\"kurss-example\">Stall (štal) — tvartas</div><div class=\"kurss-example\">Stand (štant) — būsena / vieta</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>qu</h4>\n              <p>„qu“ vokiečių kalboje dažniausiai tariamas kaip „kv“.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Qual (kvāl) — kančia</div><div class=\"kurss-example\">Quartier (kvartīr) — kvartalas / apsistojimo vieta</div><div class=\"kurss-example\">quer (kvēr) — įstrižai</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>s ir z</h4>\n              <p>Žodžio pradžioje „s“ dažnai skamba kaip „z“. Raidė „z“ vokiečių kalboje skamba kaip lietuvių „c“.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">sagen (zāgen) — sakyti</div><div class=\"kurss-example\">singen (zingen) — dainuoti</div><div class=\"kurss-example\">Rose (rōze) — rožė</div><div class=\"kurss-example\">Zahl (cāl) — skaičius</div><div class=\"kurss-example\">Zeit (cait) — laikas</div><div class=\"kurss-example\">Zink (cink) — cinkas</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>v</h4>\n              <p>Vokiečių kalboje „v“ dažnai tariamas kaip „f“. Svetimžodžiuose jis dažnai skamba kaip lietuvių „v“.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Vater (fāter) — tėvas</div><div class=\"kurss-example\">von (fon) — iš</div><div class=\"kurss-example\">viel (fīl) — daug</div><div class=\"kurss-example\">vier (fīr) — keturi</div><div class=\"kurss-example\">Villa (villa) — vila</div><div class=\"kurss-example\">Klavier (klavīr) — pianinas</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>x ir y</h4>\n              <p>„x“ tariamas kaip „ks“. „y“ kai kuriuose žodžiuose tariamas kaip „ü“.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Felix (fēliks) — Feliksas</div><div class=\"kurss-example\">Axt (akst) — kirvis</div><div class=\"kurss-example\">Mystik (mūstik) — mistika</div><div class=\"kurss-example\">Nyx (nūks) — Niksė</div><div class=\"kurss-example\">Mythe (mūte) — mitas</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ß</h4>\n              <p>„ß“ vokiečių kalboje tariamas kaip „s“.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Fuß (fūs) — pėda</div><div class=\"kurss-example\">Füße (fūse) — pėdos</div><div class=\"kurss-example\">Grüße (grūse) — sveikinimai</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Apibendrinimas</h4>\n              <ul class=\"kurss-summary-list\"><li>sch → š</li><li>sp / st pradžioje → šp / št</li><li>qu → kv</li><li>z → c</li><li>v dažnai → f</li><li>x → ks</li><li>ß → s</li></ul>\n            </section>\n",
  "kurssVerbBasicsLesson": "\n            <h3>Veiksmažodžių pagrindai</h3>\n            <p class=\"kurss-lesson-intro\">1 pamokos veiksmažodžiai ir jų asmenuotės.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Veiksmažodžiai</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">kommen — ateiti</div><div class=\"kurss-example\">gehen — eiti</div><div class=\"kurss-example\">stehen — stovėti</div><div class=\"kurss-example\">singen — dainuoti</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>kommen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich komme — aš ateinu</div><div class=\"kurss-example\">du kommst — tu ateini</div><div class=\"kurss-example\">er kommt — jis ateina</div><div class=\"kurss-example\">sie kommt — ji ateina</div><div class=\"kurss-example\">wir kommen — mes ateiname</div><div class=\"kurss-example\">ihr kommt — jūs ateinate</div><div class=\"kurss-example\">sie kommen — jie / jos ateina</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>gehen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich gehe — aš einu</div><div class=\"kurss-example\">du gehst — tu eini</div><div class=\"kurss-example\">er geht — jis eina</div><div class=\"kurss-example\">sie geht — ji eina</div><div class=\"kurss-example\">wir gehen — mes einame</div><div class=\"kurss-example\">ihr geht — jūs einate</div><div class=\"kurss-example\">sie gehen — jie / jos eina</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>stehen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich stehe — aš stoviu</div><div class=\"kurss-example\">du stehst — tu stovi</div><div class=\"kurss-example\">er steht — jis stovi</div><div class=\"kurss-example\">sie steht — ji stovi</div><div class=\"kurss-example\">wir stehen — mes stovime</div><div class=\"kurss-example\">ihr steht — jūs stovite</div><div class=\"kurss-example\">sie stehen — jie / jos stovi</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>singen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich singe — aš dainuoju</div><div class=\"kurss-example\">du singst — tu dainuoji</div><div class=\"kurss-example\">er singt — jis dainuoja</div><div class=\"kurss-example\">sie singt — ji dainuoja</div><div class=\"kurss-example\">wir singen — mes dainuojame</div><div class=\"kurss-example\">ihr singt — jūs dainuojate</div><div class=\"kurss-example\">sie singen — jie / jos dainuoja</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>2 pamokos veiksmažodžiai</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">spielen — žaisti</div><div class=\"kurss-example\">arbeiten — dirbti</div><div class=\"kurss-example\">fragen — klausti</div><div class=\"kurss-example\">antworten — atsakyti</div><div class=\"kurss-example\">rechnen — skaičiuoti</div><div class=\"kurss-example\">zeichnen — piešti</div><div class=\"kurss-example\">tun — daryti</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>spielen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich spiele — aš žaidžiu</div><div class=\"kurss-example\">du spielst — tu žaidi</div><div class=\"kurss-example\">er spielt — jis žaidžia</div><div class=\"kurss-example\">sie spielt — ji žaidžia</div><div class=\"kurss-example\">wir spielen — mes žaidžiame</div><div class=\"kurss-example\">ihr spielt — jūs žaidžiate</div><div class=\"kurss-example\">sie spielen — jie / jos žaidžia</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>arbeiten</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich arbeite — aš dirbu</div><div class=\"kurss-example\">du arbeitest — tu dirbi</div><div class=\"kurss-example\">er arbeitet — jis dirba</div><div class=\"kurss-example\">sie arbeitet — ji dirba</div><div class=\"kurss-example\">wir arbeiten — mes dirbame</div><div class=\"kurss-example\">ihr arbeitet — jūs dirbate</div><div class=\"kurss-example\">sie arbeiten — jie / jos dirba</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>fragen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich frage — aš klausiu</div><div class=\"kurss-example\">du fragst — tu klausi</div><div class=\"kurss-example\">er fragt — jis klausia</div><div class=\"kurss-example\">sie fragt — ji klausia</div><div class=\"kurss-example\">wir fragen — mes klausiame</div><div class=\"kurss-example\">ihr fragt — jūs klausiate</div><div class=\"kurss-example\">sie fragen — jie / jos klausia</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>antworten</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich antworte — aš atsakau</div><div class=\"kurss-example\">du antwortest — tu atsakai</div><div class=\"kurss-example\">er antwortet — jis atsako</div><div class=\"kurss-example\">sie antwortet — ji atsako</div><div class=\"kurss-example\">wir antworten — mes atsakome</div><div class=\"kurss-example\">ihr antwortet — jūs atsakote</div><div class=\"kurss-example\">sie antworten — jie / jos atsako</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>rechnen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich rechne — aš skaičiuoju</div><div class=\"kurss-example\">du rechnest — tu skaičiuoji</div><div class=\"kurss-example\">er rechnet — jis skaičiuoja</div><div class=\"kurss-example\">sie rechnet — ji skaičiuoja</div><div class=\"kurss-example\">wir rechnen — mes skaičiuojame</div><div class=\"kurss-example\">ihr rechnet — jūs skaičiuojate</div><div class=\"kurss-example\">sie rechnen — jie / jos skaičiuoja</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>zeichnen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich zeichne — aš piešiu</div><div class=\"kurss-example\">du zeichnest — tu pieši</div><div class=\"kurss-example\">er zeichnet — jis piešia</div><div class=\"kurss-example\">sie zeichnet — ji piešia</div><div class=\"kurss-example\">wir zeichnen — mes piešiame</div><div class=\"kurss-example\">ihr zeichnet — jūs piešiate</div><div class=\"kurss-example\">sie zeichnen — jie / jos piešia</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>tun</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich tue — aš darau</div><div class=\"kurss-example\">du tust — tu darai</div><div class=\"kurss-example\">er tut — jis daro</div><div class=\"kurss-example\">sie tut — ji daro</div><div class=\"kurss-example\">wir tun — mes darome</div><div class=\"kurss-example\">ihr tut — jūs darote</div><div class=\"kurss-example\">sie tun — jie / jos daro</div></div>\n            </section>\n",
  "kurssSentenceStructureLesson": "\n            <h3>Sakinio sandara</h3>\n            <p class=\"kurss-lesson-intro\">Klausiamajame sakinyje veiksmažodis vokiečių kalboje paprastai stovi pirmoje vietoje.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Pavyzdžiai</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Du kommst. — Tu ateini.</div><div class=\"kurss-example\">Kommst du? — Ar tu ateini?</div><div class=\"kurss-example\">Er singt. — Jis dainuoja.</div><div class=\"kurss-example\">Singt er? — Ar jis dainuoja?</div><div class=\"kurss-example\">Stehst du? — Ar tu stovi?</div><div class=\"kurss-example\">Ja, ich stehe. — Taip, aš stoviu.</div><div class=\"kurss-example\">Geht ihr? — Ar jūs einate?</div><div class=\"kurss-example\">Ja, wir gehen. — Taip, mes einame.</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>Klausimai su „was“</h4>\n              <p>Jei klausimas prasideda klausiamuoju žodžiu, veiksmažodis vokiečių kalboje paprastai stovi tiesiai už klausiamojo žodžio.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Was tust du? — Ką tu darai?</div><div class=\"kurss-example\">Was tut er? — Ką jis daro?</div><div class=\"kurss-example\">Was tut sie? — Ką ji daro?</div><div class=\"kurss-example\">Was tun sie? — Ką jie / jos daro?</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Neigimas su „nicht“</h4>\n              <p>Jei neigimas „nicht“ susijęs su veiksmažodžiu, jis vokiečių kalboje paprastai stovi po veiksmažodžio.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Ich spiele nicht. — Aš nežaidžiu.</div><div class=\"kurss-example\">Paul fragt nicht. — Paul neklausia.</div><div class=\"kurss-example\">Er kommt nicht. — Jis neateina.</div><div class=\"kurss-example\">Sie singen nicht. — Jie / jos nedainuoja.</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Sakiniai iš 2 pamokos</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Spielst du? — Ar tu žaidi?</div><div class=\"kurss-example\">Nein, ich spiele nicht, ich arbeite. — Ne, aš nežaidžiu, aš dirbu.</div><div class=\"kurss-example\">Paul fragt nicht, er arbeitet. — Paul neklausia, jis dirba.</div><div class=\"kurss-example\">Arbeitest du? — Ar tu dirbi?</div><div class=\"kurss-example\">Nein, ich arbeite nicht, ich singe. — Ne, aš nedirbu, aš dainuoju.</div><div class=\"kurss-example\">Was tut Paul? — Ką daro Paul?</div><div class=\"kurss-example\">Er spielt. — Jis žaidžia.</div><div class=\"kurss-example\">Was tut Marie? — Ką daro Marie?</div><div class=\"kurss-example\">Sie singt. — Ji dainuoja.</div><div class=\"kurss-example\">Paul spielt, aber Marie singt. — Paul žaidžia, o Marie dainuoja.</div><div class=\"kurss-example\">Singt ihr? — Ar jūs dainuojate?</div><div class=\"kurss-example\">Nein, wir singen nicht, wir arbeiten. — Ne, mes nedainuojame, mes dirbame.</div><div class=\"kurss-example\">Was tun Paul und Marie? — Ką daro Paul ir Marie?</div><div class=\"kurss-example\">Sie fragen. — Jie klausia.</div><div class=\"kurss-example\">Sie antworten nicht. — Jie neatsako.</div><div class=\"kurss-example\">Wer arbeitet? — Kas dirba?</div><div class=\"kurss-example\">Wir arbeiten. — Mes dirbame.</div><div class=\"kurss-example\">Wir rechnen und zeichnen. — Mes skaičiuojame ir piešiame.</div><div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen. — Jie / jos ateina, klausia, atsako, dirba, žaidžia, dainuoja ir eina.</div></div>\n            </section>\n",
  "kurssLesson2": "            <h3>2 pamoka</h3>\n            <p class=\"kurss-lesson-intro\">Antra pamoka: dialogai, žodžiai, tarimas, gramatika ir vertimas.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogai / sakiniai</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">Spielst du?<br>Nein, ich spiele nicht, ich arbeite.</div>\n                  <div class=\"kurss-example\">Paul fragt nicht, er arbeitet.</div>\n                  <div class=\"kurss-example\">Arbeitest du?<br>Nein, ich arbeite nicht, ich singe.</div>\n                  <div class=\"kurss-example\">Was tut Paul?<br>Er spielt.</div>\n                  <div class=\"kurss-example\">Was tut Marie?<br>Sie singt.</div>\n                  <div class=\"kurss-example\">Paul spielt, aber Marie singt.</div>\n                  <div class=\"kurss-example\">Singt ihr?<br>Nein, wir singen nicht, wir arbeiten.</div>\n                  <div class=\"kurss-example\">Was tun Paul und Marie?<br>Sie fragen.<br>Sie antworten nicht.</div>\n                  <div class=\"kurss-example\">Wer arbeitet?<br>Wir arbeiten.<br>Wir rechnen und zeichnen.</div>\n                  <div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen.</div>\n                </div>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Žodžiai</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">spielen — žaisti</div>\n                  <div class=\"kurss-example\">nein — ne</div>\n                  <div class=\"kurss-example\">nicht — ne</div>\n                  <div class=\"kurss-example\">arbeiten — dirbti</div>\n                  <div class=\"kurss-example\">fragen — klausti</div>\n                  <div class=\"kurss-example\">was tut er? — ką jis daro?</div>\n                  <div class=\"kurss-example\">was tun sie? — ką jie / jos daro?</div>\n                  <div class=\"kurss-example\">aber — bet</div>\n                  <div class=\"kurss-example\">antworten — atsakyti</div>\n                  <div class=\"kurss-example\">rechnen — skaičiuoti</div>\n                  <div class=\"kurss-example\">zeichnen — piešti</div>\n                  <div class=\"kurss-example\">Marie — Marija</div>\n                </div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Tarimas</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Vārdos ich, nicht, rechnen, zeichnen skaņu ch izrunā mīksti, apmēram tā, kā latviski vārdos: technika, Frīdrihs.</div><div class=\"kurss-example\">Vārdos arbeiten, zeichnen divskani ei izrunā apmēram kā latviešu plato e skaņu, kam seko i.</div><div class=\"kurss-example\">Līdzskaņu kopojumu sp izrunā kā šp: spielen (špīlen).</div><div class=\"kurss-example\">Darbības vārdā tun u izrunājams gari visās personās.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatika</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>1</span>Galūnės su e</h4>\n                  <div class=\"lesson1-grammar-note\">Jei veiksmažodžio kamienas baigiasi t, d, chn, tuomet linksniuojant prieš galūnes -st ir -t stovi e.</div>\n                  <h5 class=\"lesson2-subtitle\">arbeiten</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich arbeite</div><div class=\"kurss-example\">du arbeitest</div><div class=\"kurss-example\">er arbeitet</div><div class=\"kurss-example\">sie arbeitet</div><div class=\"kurss-example\">wir arbeiten</div><div class=\"kurss-example\">ihr arbeitet</div><div class=\"kurss-example\">sie arbeiten</div></div>\n                  <h5 class=\"lesson2-subtitle\">rechnen</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich rechne</div><div class=\"kurss-example\">du rechnest</div><div class=\"kurss-example\">er rechnet</div><div class=\"kurss-example\">sie rechnet</div><div class=\"kurss-example\">wir rechnen</div><div class=\"kurss-example\">ihr rechnet</div><div class=\"kurss-example\">sie rechnen</div></div>\n                  <h5 class=\"lesson2-subtitle\">tun</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich tue</div><div class=\"kurss-example\">du tust</div><div class=\"kurss-example\">er tut</div><div class=\"kurss-example\">sie tut</div><div class=\"kurss-example\">wir tun</div><div class=\"kurss-example\">ihr tut</div><div class=\"kurss-example\">sie tun</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>2</span>Klausiamasis žodis</h4>\n                  <div class=\"lesson1-grammar-note\">Klausiamuosiuose sakiniuose, kurie prasideda klausiamuoju žodžiu, pavyzdžiui: ką? kas? kuris? kodėl? kam? ir t. t., veiksmažodis stovi tiesiai už klausiamojo žodžio.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Was tust du? — Ką tu darai?</div><div class=\"kurss-example\">Was tut er? — Ką jis daro?</div><div class=\"kurss-example\">Was tut sie? — Ką ji daro?</div><div class=\"kurss-example\">Was tun sie? — Ką jie / jos daro?</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>3</span>Neigimas su nicht</h4>\n                  <div class=\"lesson1-grammar-note\">Jei neigimas nicht susijęs su veiksmažodžiu, tuomet neigiamas žodis stovi po veiksmažodžio.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Er kommt nicht. — Jis neateina.</div><div class=\"kurss-example\">Sie singen nicht. — Jie nedainuoja.</div></div>\n                </section>\n              </div>\n            </details>\n                                    <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Išversk</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson2-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"2 pamokos vertimo kortelė\">\n                    <span class=\"lesson1-training-progress\">2 pamoka · Išversk: 1 / 15</span>\n                    <span class=\"lesson1-training-text\">Kas klausia?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Spustelėk kortelę, kad pamatytum vokiečių vertimą. Po atsakymo kitas spustelėjimas parodys kitą kortelę.</p>\n                </div>\n              </div>\n            </details>\n",
  "kurssLesson6": "\n    <h3>6 pamoka</h3>\n    <p class=\"kurss-lesson-intro\">Skaičiai, daugiskaita, umliautai ir daiktavardžių daugiskaitos formos.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogai / sakiniai</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier liegt ein Bleistift.</div><div class=\"kurss-example\">Dort liegen einige Messer.</div><div class=\"kurss-example\">Edgar nimmt ein Messer, zwei Messer, drei Messer.</div><div class=\"kurss-example\">Er legt die Messer wieder hin.</div><div class=\"kurss-example\">Alle Messer sind scharf.</div><div class=\"kurss-example\">Dann nimmt er wieder ein Messer.</div><div class=\"kurss-example\">Er macht das Messer auf.</div><div class=\"kurss-example\">Er nimmt den Bleistift.</div><div class=\"kurss-example\">Er spitzt den Bleistift an.</div><div class=\"kurss-example\">Er legt das Messer hin.</div><div class=\"kurss-example\">Er setzt sich und zeichnet.</div><div class=\"kurss-example\">Was zeichnet er? Er zeichnet einen Schlüssel.</div><div class=\"kurss-example\">Gertrud zeichnet ein Fenster und eine Tafel.</div><div class=\"kurss-example\">Anna zeichnet einen Garten.</div><div class=\"kurss-example\">Hier liegen vier Löffel.</div><div class=\"kurss-example\">Dort liegen fünf Nadeln.</div><div class=\"kurss-example\">Gertrud kommt und zählt die Löffel: das ist ein Löffel; das sind zwei, drei, vier Löffel.</div><div class=\"kurss-example\">Anna zählt die Nadeln: das ist eine Nadel; das sind zwei, drei, vier, fünf Nadeln.</div><div class=\"kurss-example\">Wieviel Nadeln sind hier?</div><div class=\"kurss-example\">Hier ist eine Nadel.</div><div class=\"kurss-example\">Dort sind zwei, drei, vier Nadeln.</div><div class=\"kurss-example\">Fünf Schlüssel sind hier.</div><div class=\"kurss-example\">Sechs Löffel sind dort.</div><div class=\"kurss-example\">Was ist das?</div><div class=\"kurss-example\">Das ist ein Hammer. Das sind fünf Hämmer.</div><div class=\"kurss-example\">Das ist ein Deckel. Das sind sechs Deckel.</div><div class=\"kurss-example\">Das ist ein Eimer. Das sind sieben Eimer.</div><div class=\"kurss-example\">Das ist ein Teller. Das sind acht Teller.</div><div class=\"kurss-example\">Das ist ein Wagen. Das sind neun Wagen.</div><div class=\"kurss-example\">Das ist ein Schlitten. Das sind zehn Schlitten.</div><div class=\"kurss-example\">Wie sind die Dinge?</div><div class=\"kurss-example\">Der Hammer ist klein. Die Hämmer sind klein.</div><div class=\"kurss-example\">Der Deckel ist groß. Die Deckel sind groß.</div><div class=\"kurss-example\">Der Eimer ist voll. Die Eimer sind voll.</div><div class=\"kurss-example\">Der Teller ist leer. Die Teller sind leer.</div><div class=\"kurss-example\">Der Wagen ist schwer. Die Wagen sind schwer.</div><div class=\"kurss-example\">Der Schlitten ist leicht. Die Schlitten sind leicht.</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Žodžiai</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">liegt — randasi, yra, guli</div><div class=\"kurss-example\">der Bleistift (bleištift) — pieštukas</div><div class=\"kurss-example\">einige (einige) — keli</div><div class=\"kurss-example\">hinlegen — padėti</div><div class=\"kurss-example\">legt hin — padeda</div><div class=\"kurss-example\">wieder (vīder) — vėl</div><div class=\"kurss-example\">aufmachen — atidaryti</div><div class=\"kurss-example\">er macht auf — jis atidaro</div><div class=\"kurss-example\">anspitzen (anšpicen) — pasmailinti</div><div class=\"kurss-example\">er spitzt an — jis pasmailina</div><div class=\"kurss-example\">sich setzen — atsisėsti</div><div class=\"kurss-example\">setzt sich — atsisėda</div><div class=\"kurss-example\">der Schlüssel (šlūsel) — raktas</div><div class=\"kurss-example\">das Fenster (fenster) — langas</div><div class=\"kurss-example\">die Tafel (dī tāfel) — lenta</div><div class=\"kurss-example\">der Garten — sodas</div><div class=\"kurss-example\">der Löffel — šaukštas</div><div class=\"kurss-example\">zählen (cēlen) — skaičiuoti</div><div class=\"kurss-example\">die Nadel — adata</div><div class=\"kurss-example\">was ist das — kas tai yra?</div><div class=\"kurss-example\">der Hammer — kūjis</div><div class=\"kurss-example\">die Hämmer — kūjai</div><div class=\"kurss-example\">der Deckel (dēr dekel) — dangtis</div><div class=\"kurss-example\">der Teller — lėkštė</div><div class=\"kurss-example\">der Wagen — vežimas</div><div class=\"kurss-example\">der Schlitten — rogės, kamanos</div><div class=\"kurss-example\">das Ding — daiktas</div><div class=\"kurss-example\">die Dinge — daiktai</div><div class=\"kurss-example\">wie sind die Dinge? — kokie yra daiktai?</div><div class=\"kurss-example\">voll (fōl) — pilnas</div><div class=\"kurss-example\">leer (lēr) — tuščias</div><div class=\"kurss-example\">schwer (švēr) — sunkus</div><div class=\"kurss-example\">leicht — lengvas</div><div class=\"kurss-example\">der Eimer — kibiras</div><div class=\"kurss-example\">wieviel (vīfīl) — kiek</div><div class=\"kurss-example\">wieviel Nadeln — kiek adatų</div><div class=\"kurss-example\">hier (hīr) — čia</div><div class=\"kurss-example\">dort — tur</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Tarimas</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ä ir patskaņa a pārskanojums, un to izrunā kā īso vai garo šauro e.</div><div class=\"kurss-example\">Piemēri: das Mädchen (mētchen), die Bänke (dī benke), der Vater (dēr fāter), die Väter (dī fēter).</div><div class=\"kurss-example\">ü ir patskaņa u pārskanojums. To izrunājot, lūpas ļoti jāapaļo un jāmēģina ar apaļi veidotām lūpām izrunāt i.</div><div class=\"kurss-example\">Piemēri: fünf, der Schlüssel (šlūsel).</div><div class=\"kurss-example\">ö izrunā ar apaļi veidotām lūpām, mēģinot izrunāt e: der Löffel.</div><div class=\"kurss-example\">Divkāršots patskanis apzīmē garu patskani: leer (lēr).</div><div class=\"kurss-example\">Divskani eu izrunā kā oi: neun (noin).</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatika</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Gramatika ir paaiškinimai</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Salikta darbības vārda uzsvērtais priedēklis tagadnē atdalās no darbības vārda un stāv teikuma beigās.</div><div class=\"kurss-example\">Piemēri: hinlegen — er legt hin; aufmachen — er macht auf; anspitzen — er spitzt an.</div><div class=\"kurss-example\">Skaitļa vārds viens ir visās trīs kārtās, ja to lieto ar lietvārdu: vīriešu kārtā ein, sieviešu kārtā eine, vidējā kārtā ein.</div><div class=\"kurss-example\">Piemēri: ein Schüler — vienas mokinys; eine Schülerin — viena mokinė; ein Kind — vienas vaikas.</div><div class=\"kurss-example\">Skaitļi: eins, zwei, drei, vier (fīr), fünf, sechs (zeks), sieben (zīben), acht, neun (noin), zehn (cēn).</div><div class=\"kurss-example\">Saitaiņa vācu valodā ir vienskaitļa un daudzskaitļa forma: der Schüler ist klein; die Schüler sind klein.</div><div class=\"kurss-example\">Norādāmais vietniekvārds tas latviešu valodā mainās skaitlī un kārtā, bet vācu valodā lieto vienu formu: das.</div><div class=\"kurss-example\">Piemēri: tas ir veseris — das ist ein Hammer; tai yra adata — das ist eine Nadel; tai yra kūjai — das sind Hämmer; tai yra adatos — das sind Nadeln.</div><div class=\"kurss-example\">Der Wagen — vežimas ir der Schlitten — rogės lietuvių kalboje dažnai laikomi daugiskaitos žodžiais, bet vokiečių kalboje šiuos žodžius vartoja ir vienaskaitoje, ir daugiskaitoje.</div><div class=\"kurss-example\">Vīriešu un vidējās kārtas lietvārdi ar galotni -er, -el, -en daugiskaitoje dažnai nekeičia galūnės.</div><div class=\"kurss-example\">Piemēri: der Hammer — die Hämmer; der Garten — die Gärten; das Fenster — die Fenster; das Messer — die Messer.</div><div class=\"kurss-example\">Sieviešu kārtas lietvārdi ar galotni -el, -er daugiskaitoje gauna -n.</div><div class=\"kurss-example\">Piemēri: die Nadel — die Nadeln; die Feder — die Federn.</div><div class=\"kurss-example\">Izņēmumi: die Mutter (māte) — die Mütter (motinos); die Tochter (dukra) — die Töchter (dukros).</div><div class=\"kurss-example\">Nenoteiktajam artikulam daudzskaitļa nav: das ist ein Wagen — das sind Wagen; das ist eine Nadel — das sind Nadeln.</div><div class=\"kurss-example\">Stāstāmā teikumā izteicējs-veiksmažodis stovi antroje vietoje: er legt den Schlüssel hin; dann legt er den Schlüssel hin.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Išversk</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson6-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"6 pamokos vertimo kortelė\"><span class=\"lesson1-training-progress\">6 pamoka · Išversk: 1 / 21</span><span class=\"lesson1-training-text\">Paul ima pieštuką ir piešia.</span></button><p class=\"lesson1-training-hint\">Spustelėk kortelę, kad pamatytum vokiečių vertimą. Po atsakymo kitas spustelėjimas parodys kitą kortelę.</p></div></div>\n    </details>\n  ",
  "kurssLesson5": "\n    <h3>5 pamoka</h3>\n    <p class=\"kurss-lesson-intro\">Wen?, akuzatyvas, sitzen, fragen ir -in galūnė.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogai / sakiniai</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">Wer sitzt und fragt? Der Lehrer sitzt und fragt.</div>\n        <div class=\"kurss-example\">Wer steht und antwortet? Der Schüler steht und antwortet.</div>\n        <div class=\"kurss-example\">Wie antwortet der Schüler? Der Schüler antwortet gut.</div>\n        <div class=\"kurss-example\">Wen lobt der Lehrer? Der Lehrer lobt den Schüler.</div>\n        <div class=\"kurss-example\">Wie ist der Schüler? Der Schüler ist klein.</div>\n        <div class=\"kurss-example\">Ist der Schüler klein oder groß? Er ist klein.</div>\n        <div class=\"kurss-example\">Wen fragt die Lehrerin? Die Lehrerin fragt die Schülerin.</div>\n        <div class=\"kurss-example\">Wie antwortet die Schülerin? Die Schülerin antwortet schlecht.</div>\n        <div class=\"kurss-example\">Was tut die Lehrerin? Sie tadelt die Schülerin.</div>\n        <div class=\"kurss-example\">Die Schülerin ist nicht klein, sie ist groß.</div>\n        <div class=\"kurss-example\">Ein Kind spielt. Das Kind ist artig.</div>\n        <div class=\"kurss-example\">Die Mutter liebt das Kind. Der Vater lobt das Kind.</div>\n      </div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Žodžiai</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">sitzen (zicen) — sėdėti</div>\n        <div class=\"kurss-example\">fragen (frāgen) — klausti</div>\n        <div class=\"kurss-example\">der Lehrer (dēr lērer) — mokytojas</div>\n        <div class=\"kurss-example\">gut (gūt) — gerai</div>\n        <div class=\"kurss-example\">wen (vēn) — ką</div>\n        <div class=\"kurss-example\">loben — girti</div>\n        <div class=\"kurss-example\">der Schüler (šūler) — mokinys</div>\n        <div class=\"kurss-example\">klein — mažas</div>\n        <div class=\"kurss-example\">groß (grōs) — didelis</div>\n        <div class=\"kurss-example\">die Lehrerin — mokytoja</div>\n        <div class=\"kurss-example\">die Schülerin — mokinė</div>\n        <div class=\"kurss-example\">schlecht (šleht) — blogai</div>\n        <div class=\"kurss-example\">tadeln — barti</div>\n        <div class=\"kurss-example\">oder (ōder) — arba</div>\n        <div class=\"kurss-example\">das Kind (kint) — vaikas</div>\n        <div class=\"kurss-example\">artig (ārtich) — paklusnus</div>\n        <div class=\"kurss-example\">die Mutter — motina</div>\n        <div class=\"kurss-example\">lieben (līben) — mylėti</div>\n        <div class=\"kurss-example\">der Vater (fāter) — tėvas</div>\n      </div></div>\n    </details>\n\n        <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Tarimas</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">tz ir dubultots z skanis un izrunājams kā z: sitzen (zicen).</div>\n        <div class=\"kurss-example\">v vācu vārdos izrunā kā f: der Vater (fāter).</div>\n        <div class=\"kurss-example\">ß sauc par escet un izrunā kā latviešu s: groß (grōs), weiß (veis).</div>\n      </div></div>\n    </details>\n\n<details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatika</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Nominatyvas ir akuzatyvas</h4><div class=\"lesson1-grammar-note\">Lietuvių kalboje nominatyvas atsako į klausimą kas?, o akuzatyvas — į klausimą ką?.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Vācu valodā nominatīvā jautājums ir wer? personām un was? priekšmetiem.</div><div class=\"kurss-example\">Akuzatīvā jautājums ir wen? personām un was? priekšmetiem.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Artikelio pasikeitimas akuzatyve</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Akkusativ: den Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">sitzen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich sitze</div><div class=\"kurss-example\">du sitzt</div><div class=\"kurss-example\">er/sie/es sitzt</div><div class=\"kurss-example\">wir sitzen</div><div class=\"kurss-example\">ihr sitzt</div><div class=\"kurss-example\">sie sitzen</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">fragen + akuzatyvas</h4><div class=\"lesson1-grammar-note\">Veiksmažodis fragen vokiečių kalboje reikalauja akuzatyvo.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wen fragt der Lehrer?</div><div class=\"kurss-example\">Der Lehrer fragt den Schüler.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">-in galūnė</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Daudz sieviešu kārtas vārdu atvasina ar galotni -in.</div><div class=\"kurss-example\">die Lehrerin</div><div class=\"kurss-example\">die Schülerin</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Veiksmažodžio vieta</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Stāstāmā teikumā darbības vārds stāv otrā vietā.</div><div class=\"kurss-example\">Dann geht das Mädchen hinaus und arbeitet.</div><div class=\"kurss-example\">Das Mädchen geht dann hinaus und arbeitet.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Išversk</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson5-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"5 pamokos vertimo kortelė\"><span class=\"lesson1-training-progress\">5 pamoka · Išversk: 1 / 16</span><span class=\"lesson1-training-text\">Ką myli tėvas?</span></button><p class=\"lesson1-training-hint\">Spustelėk kortelę, kad pamatytum vokiečių vertimą. Po atsakymo kitas spustelėjimas parodys kitą kortelę.</p></div></div>\n    </details>\n  ",
  "kurssLesson4": "            <h3>4 pamoka</h3>\n            <p class=\"kurss-lesson-intro\">Akuzatyvas, nehmen, hinlegen, hinausgehen ir būdvardžiai.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogai / sakiniai</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Paul kommt und nimmt einen Federhalter.</div><div class=\"kurss-example\">Er zeigt den Federhalter.</div><div class=\"kurss-example\">Er fragt: „Wie ist der Federhalter?“</div><div class=\"kurss-example\">Olga antwortet: „Der Federhalter ist schwarz.“</div><div class=\"kurss-example\">Ist der Federhalter weiß? Nein, der Federhalter ist nicht weiß, er ist schwarz.</div><div class=\"kurss-example\">Marie kommt und nimmt eine Feder.</div><div class=\"kurss-example\">Sie fragt: „Wie ist die Feder?“</div><div class=\"kurss-example\">Olga antwortet: „Die Feder ist spitz.“</div><div class=\"kurss-example\">Ist die Feder stumpf? Nein, die Feder ist nicht stumpf, sie ist spitz.</div><div class=\"kurss-example\">Was legt das Mädchen hin? Es legt die Feder hin.</div><div class=\"kurss-example\">Was nimmst du? Ich nehme ein Messer.</div><div class=\"kurss-example\">Wie ist das Messer? Das Messer ist scharf.</div><div class=\"kurss-example\">Ist das Messer stumpf? Nein, es ist nicht stumpf, es ist scharf.</div><div class=\"kurss-example\">Was legst du hin? Ich lege das Messer, die Feder und den Federhalter hin.</div><div class=\"kurss-example\">Dann gehe ich hinaus und arbeite.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Žodžiai</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">nehmen (nēmen) — imti</div><div class=\"kurss-example\">er nimmt (nimt) — jis ima</div><div class=\"kurss-example\">der Federhalter (dēr fēderhalter) — plunksnakotis</div><div class=\"kurss-example\">einen Federhalter — plunksnakotį</div><div class=\"kurss-example\">zeigen — rodyti</div><div class=\"kurss-example\">schwarz (švarc) — juodas</div><div class=\"kurss-example\">weiß (veis) — baltas</div><div class=\"kurss-example\">die Feder (dī fēder) — plunksna</div><div class=\"kurss-example\">eine Feder — plunksną</div><div class=\"kurss-example\">spitz (špic) — smailus</div><div class=\"kurss-example\">hinlegen — padėti</div><div class=\"kurss-example\">legt hin — padeda</div><div class=\"kurss-example\">das Mädchen (mētchen) — mergaitė</div><div class=\"kurss-example\">das Messer — peilis</div><div class=\"kurss-example\">ein Messer — peilį</div><div class=\"kurss-example\">scharf — aštrus</div><div class=\"kurss-example\">stumpf (štumpf) — neaštrus, atšipęs</div><div class=\"kurss-example\">dann — tada</div><div class=\"kurss-example\">hinaus — laukan</div><div class=\"kurss-example\">hinausgehen — išeiti, eiti laukan</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Tarimas</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Galotnes -en, -er, -el yra nekirčiuotos, todėl e šiose galūnėse sunkiai išgirstamas: kommen, nehmen, der Federhalter.</div><div class=\"kurss-example\">h vācu valodā var būt gan skaņa, gan garumzīme iepriekšējam patskanim.</div><div class=\"kurss-example\">Ja h ir garumzīme, to neizrunā kā skaņu: nehmen (nēmen).</div><div class=\"kurss-example\">Ja patskanim seko tikai viens līdzskanis, patskani izrunā gari: die (dī) Feder (fēder), den (dēn).</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatika</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Akuzatyvas</h4><div class=\"lesson1-grammar-note\">Moteriškojoje ir niekatrojoje giminėje akuzatyvas sutampa su nominatyvu. Keičiasi tik vyriškoji giminė.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Nominativ: ein Federhalter, eine Feder, ein Messer.</div><div class=\"kurss-example\">Akkusativ: einen Federhalter, eine Feder, ein Messer.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>nehmen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich nehme</div><div class=\"kurss-example\">du nimmst</div><div class=\"kurss-example\">er/sie nimmt</div><div class=\"kurss-example\">wir nehmen</div><div class=\"kurss-example\">ihr nehmt</div><div class=\"kurss-example\">sie nehmen</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Įvardžiai</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er — vyriškoji giminė</div><div class=\"kurss-example\">sie — moteriškoji giminė</div><div class=\"kurss-example\">es — niekatroji giminė</div><div class=\"kurss-example\">daudzskaitlī — sie</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Atskiriamieji veiksmažodžiai</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">hinlegen → ich lege das Messer hin</div><div class=\"kurss-example\">hinausgehen → Marie geht hinaus</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>Būdvardžiai</h4><div class=\"lesson1-grammar-note\">Jei būdvardis sakinyje yra tarinys, jis nekinta nei gimine, nei skaičiumi.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist klein</div><div class=\"kurss-example\">die Feder ist klein</div><div class=\"kurss-example\">das Messer ist klein</div><div class=\"kurss-example\">die Messer sind klein</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>6</span>Neigimas su nicht</h4><div class=\"lesson1-grammar-note\">Jei nicht neigia būdvardį, jis stovi prieš neigiamą žodį.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist nicht weiß</div><div class=\"kurss-example\">das Messer ist nicht scharf</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>7</span>-chen / -lein</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Lietvārdi ar galotni -chen ir -lein yra niekatrosios giminės: das Mädchen.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Išversk</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson4-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"4 pamokos vertimo kortelė\"><span class=\"lesson1-training-progress\">4 pamoka · Išversk: 1 / 16</span><span class=\"lesson1-training-text\">Mergaitė ima plunksnakotį.</span></button><p class=\"lesson1-training-hint\">Spustelėk kortelę, kad pamatytum vokiečių vertimą. Po atsakymo kitas spustelėjimas parodys kitą kortelę.</p></div></div></details>",
  "kurssLesson3": "            <h3>3 pamoka</h3>\n            <p class=\"kurss-lesson-intro\">Trečia pamoka: dialogai, žodžiai, tarimas, gramatika ir vertimas.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogai / sakiniai</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wer rechnet und zeichnet?<br>Wir rechnen und zeichnen.</div><div class=\"kurss-example\">Wer kommt?<br>Paul und Anna kommen.</div><div class=\"kurss-example\">Was steht hier?<br>Hier steht ein Tisch.</div><div class=\"kurss-example\">Was steht dort?<br>Dort steht eine Bank.</div><div class=\"kurss-example\">Was liegt hier?<br>Hier liegt ein Buch.</div><div class=\"kurss-example\">Was liegt dort?<br>Dort liegt ein Heft.</div><div class=\"kurss-example\">Was hängt hier?<br>Hier hängt ein Bild.</div><div class=\"kurss-example\">Was hängt dort?<br>Dort hängt eine Tafel.</div><div class=\"kurss-example\">Wie ist das Buch?<br>Das Buch ist dick.</div><div class=\"kurss-example\">Wie ist das Heft?<br>Das Heft ist dünn.</div><div class=\"kurss-example\">Wie ist die Bank?<br>Die Bank ist niedrig.</div><div class=\"kurss-example\">Wie ist der Tisch?<br>Der Tisch ist hoch.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Žodžiai</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wer — kas</div><div class=\"kurss-example\">was — kas</div><div class=\"kurss-example\">hier — čia</div><div class=\"kurss-example\">dort — tur</div><div class=\"kurss-example\">der Tisch — stalas</div><div class=\"kurss-example\">ein Tisch — stalas</div><div class=\"kurss-example\">die Bank — suolas</div><div class=\"kurss-example\">eine Bank — suolas</div><div class=\"kurss-example\">liegen — gulėti</div><div class=\"kurss-example\">liegt hier ein Buch? — ar čia yra / randasi knyga?</div><div class=\"kurss-example\">das Buch — knyga</div><div class=\"kurss-example\">ein Buch — knyga</div><div class=\"kurss-example\">hängen — kabėti</div><div class=\"kurss-example\">das Bild — paveikslas</div><div class=\"kurss-example\">ein Bild — paveikslas</div><div class=\"kurss-example\">die Tafel — lenta</div><div class=\"kurss-example\">eine Tafel — lenta</div><div class=\"kurss-example\">wie — koks, kokia</div><div class=\"kurss-example\">ist — yra</div><div class=\"kurss-example\">dick — storas, tankus</div><div class=\"kurss-example\">das Heft — sąsiuvinis</div><div class=\"kurss-example\">ein Heft — sąsiuvinis</div><div class=\"kurss-example\">dünn — plonas, laibas</div><div class=\"kurss-example\">niedrig — žemas</div><div class=\"kurss-example\">hoch — aukštas</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Tarimas</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Garo ī skaņu vācu valodā apzīmē ar ie: liegen (līgen), hier (hīr), wie (vī).</div><div class=\"kurss-example\">ck ir divkāršs k: dick (dikk).</div><div class=\"kurss-example\">Īpašības un apstākļu vārdos galotne -ig skamba kaip lengvas -ich: niedrig (nīdrich).</div><div class=\"kurss-example\">Ja galotne -ig baigiasi e: -ige, tuomet g tariamas kaip tikras g skambesys: niedrige (nīdrige) Bänke.</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatika</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Sakinio veiksnys</h4><div class=\"lesson1-grammar-note\">Sakinio veiksnys vokiečių kalboje atsako į klausimą wer? / was? ir stovi nominatyve.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Ar wer? jautā pēc personām.</div><div class=\"kurss-example\">Ar was? jautā pēc priekšmetiem.</div><div class=\"kurss-example\">Wer singt? — Sie singt.</div><div class=\"kurss-example\">Was liegt hier? — Hier liegt ein Buch.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Artikeliai</h4><div class=\"lesson1-grammar-note\">Vokiečių kalboje daiktavardis turi 3 gimines: vyriškąją, moteriškąją ir niekatrąją. Prieš daiktavardį paprastai stovi žodelis, vadinamas artikeliu. Šis žodelis nėra verčiamas.</div><h5 class=\"lesson2-subtitle\">Noteiktais artikuls</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">vīriešu kārta — der</div><div class=\"kurss-example\">sieviešu kārta — die</div><div class=\"kurss-example\">vidējā kārta — das</div><div class=\"kurss-example\">Daudzskaitlī noteiktais artikuls visām trim kārtām ir die.</div><div class=\"kurss-example\">der Tisch — die Tische</div><div class=\"kurss-example\">die Bank — die Bänke</div><div class=\"kurss-example\">das Heft — die Hefte</div></div><h5 class=\"lesson2-subtitle\">Nenoteiktais artikuls</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">vīriešu kārta — ein</div><div class=\"kurss-example\">sieviešu kārta — eine</div><div class=\"kurss-example\">vidējā kārta — ein</div><div class=\"kurss-example\">Nenoteiktajam artikulam daudzskaitļa nav.</div><div class=\"kurss-example\">ein Tisch — Tische</div><div class=\"kurss-example\">ein Heft — Hefte</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Tikriniai vardai</h4><div class=\"lesson1-grammar-note\">Prieš tikrinius vardus artikelis nevartojamas.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans spielt, aber Marie singt.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Veiksmažodžio vieta</h4><div class=\"lesson1-grammar-note\">Pasakojamajame sakinyje veiksmažodis stovi antroje vietoje.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier hängt eine Karte.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>stehen / liegen / hängen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Vāciski par priekšmetiem, kas stāv vertikāli, saka, ka priekšmets stāv:<br>der Tisch steht<br>die Bank steht</div><div class=\"kurss-example\">Par priekšmetiem, kas atrodas horizontālā stāvoklī, saka, ka tie guļ:<br>das Buch liegt<br>das Heft liegt</div><div class=\"kurss-example\">Priekšmeti var arī karāties:<br>die Karte hängt<br>die Tafel hängt</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Išversk</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson3-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"3 pamokos vertimo kortelė\"><span class=\"lesson1-training-progress\">3 pamoka · Išversk: 1 / 22</span><span class=\"lesson1-training-text\">Ar tu skaičiuoji?</span></button><p class=\"lesson1-training-hint\">Spustelėk kortelę, kad pamatytum vokiečių vertimą. Po atsakymo kitas spustelėjimas parodys kitą kortelę.</p></div></div></details>",
  "kurssLesson7": "            <h3>7 pamoka</h3>\n            <p class=\"kurss-lesson-intro\">Septinta pamoka: liepiamoji nuosaka, kreipimosi forma ir daugiskaita.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogai / sakiniai</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans, singe ein Lied! Was tust du? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans und Olga, singt ein Lied! Was tut ihr? Wir singen ein Lied.</div><div class=\"kurss-example\">Fräulein Müller, singen Sie, bitte, ein Lied! Was tun Sie? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans, zähle die Teller! Was tut Hans? Er zählt die Teller.</div><div class=\"kurss-example\">Hans und Olga, zählt die Teller! Was tun Hans und Olga? Sie zählen die Teller.</div><div class=\"kurss-example\">Fräulein Müller, zählen Sie, bitte, die Teller!</div><div class=\"kurss-example\">Hans, öffne das Fenster! Was tut Hans? Er öffnet das Fenster.</div><div class=\"kurss-example\">Hans und Olga, öffnet die Fenster! Was tun Hans und Olga? Sie öffnen die Fenster.</div><div class=\"kurss-example\">Fräulein Müller, öffnen Sie, bitte, alle Fenster!</div><div class=\"kurss-example\">Fräulein Müller öffnet alle Fenster.</div><div class=\"kurss-example\">Das ist der Spiegel. Das sind die Spiegel.</div><div class=\"kurss-example\">Das ist der Lappen. Das sind die Lappen.</div><div class=\"kurss-example\">Das ist der Spaten. Das sind die Spaten.</div><div class=\"kurss-example\">Das ist der Besen. Das sind die Besen.</div><div class=\"kurss-example\">Das ist die Schaufel. Das sind die Schaufeln.</div><div class=\"kurss-example\">Das ist die Schüssel. Das sind die Schüsseln.</div><div class=\"kurss-example\">Das ist das Zimmer. Das sind die Zimmer.</div><div class=\"kurss-example\">Das ist das Ufer. Das sind die Ufer.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Žodžiai</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">singen — dainuoti</div><div class=\"kurss-example\">singe — dainuok</div><div class=\"kurss-example\">singt — dainuokite</div><div class=\"kurss-example\">singen Sie — dainuokite</div><div class=\"kurss-example\">das Lied (das līt) — daina</div><div class=\"kurss-example\">Sie — Jūs</div><div class=\"kurss-example\">zählen — skaičiuoti</div><div class=\"kurss-example\">das Fräulein (froilein) — panelė</div><div class=\"kurss-example\">der Müller — malūnininkas</div><div class=\"kurss-example\">öffnen — atidaryti</div><div class=\"kurss-example\">das Fenster (fenster) — langas</div><div class=\"kurss-example\">alle — visi</div><div class=\"kurss-example\">der Spiegel (špīgel) — veidrodis</div><div class=\"kurss-example\">der Lappen — skuduras, šluostė</div><div class=\"kurss-example\">der Spaten — kastuvas</div><div class=\"kurss-example\">der Besen — šluota</div><div class=\"kurss-example\">die Schaufel — semtuvėlis</div><div class=\"kurss-example\">die Schüssel — dubenis</div><div class=\"kurss-example\">das Zimmer — kambarys</div><div class=\"kurss-example\">das Ufer (ūfer) — krantas</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Tarimas</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">sp vārda vai zilbes sākumā izrunā kā šp: der Spiegel (dēr špīgel).</div><div class=\"kurss-example\">sch izrunā kā latviešu š: die Schaufel (dī šaufel), die Schüssel (dī šūsel).</div><div class=\"kurss-example\">Divskani äu izrunā kā latviešu oi: das Fräulein (das froilein).</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatika</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Liepiamoji nuosaka</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Pavēles izteiksme vienskaitļa 2. personā atbilst darbības vārda 2. personai vienskaitlī bez personu galotnes -st, pridedant galūnę -e.</div><div class=\"kurss-example\">Piemēri: antworte!, arbeite!, öffne!, zeichne!</div><div class=\"kurss-example\">Ļoti bieži galotne -e nevartojama, jei su ja liepiamoji forma tampa vienskiemenė: geh!, steh!, komm!, tu!, sing!, frag!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Daugiskaitos liepiamoji forma</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Pavēles forma 2. personā daudzskaitlī līdzinās tagadnes daudzskaitļa 2. personai, bet tiek lietota bez vietniekvārda.</div><div class=\"kurss-example\">Piemēri: antwortet!, arbeitet!, öffnet!, zeichnet!, geht!, steht!, tut!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Kreipimosi forma su Sie</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Uzrunas forma ar “Jūs” līdzinās daudzskaitļa 3. personai. Vietniekvārds Sie rakstāms ar lielo burtu un stāv pēc darbības vārda.</div><div class=\"kurss-example\">Piemēri: antworten Sie!, arbeiten Sie!, öffnen Sie!, zeichnen Sie!, gehen Sie!, stehen Sie!, tun Sie!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>öffnen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Darbības vārdam öffnen vieglākas izrunas dēļ 2. un 3. personā vienskaitlī un 2. personā daudzskaitlī starp celmu un galotni iesprauž e: du öffnest, er öffnet, ihr öffnet.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Übung / Pratimas</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson7-exercise-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"7 pamokos pratimo kortelė\"><span class=\"lesson1-training-progress\">7 pamoka · Übung: 1 / 16</span><span class=\"lesson1-training-text\">fragen — klausti</span></button><p class=\"lesson1-training-hint\">Palieskite kortelę, kad pamatytumėte liepiamąsias formas.</p></div></div></details>",
  "kurssLesson1": "            <h3>1 pamoka</h3>\n            <p class=\"kurss-lesson-intro\">Pirma pamoka: veiksmažodžiai esamajame laike, žodeliai, tarimas, gramatika ir vertimas.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Veiksmažodžiai esamajame laike</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info\">Veiksmažodžiai ir jų asmenuotės esamajame laike.</div>\n                <div class=\"lesson1-verb-cards\">\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>kommen — ateiti</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>komme</strong><span>aš ateinu</span><span>du</span><strong>kommst</strong><span>tu ateini</span><span>er / sie</span><strong>kommt</strong><span>jis / ji ateina</span><span>wir</span><strong>kommen</strong><span>mes ateiname</span><span>ihr</span><strong>kommt</strong><span>jūs ateinate</span><span>sie / Sie</span><strong>kommen</strong><span>jie / Jūs ateina</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>gehen — eiti</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>gehe</strong><span>aš einu</span><span>du</span><strong>gehst</strong><span>tu eini</span><span>er / sie</span><strong>geht</strong><span>jis / ji eina</span><span>wir</span><strong>gehen</strong><span>mes einame</span><span>ihr</span><strong>geht</strong><span>jūs einate</span><span>sie / Sie</span><strong>gehen</strong><span>jie / Jūs eina</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>stehen — stovėti</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>stehe</strong><span>aš stoviu</span><span>du</span><strong>stehst</strong><span>tu stovi</span><span>er / sie</span><strong>steht</strong><span>jis / ji stovi</span><span>wir</span><strong>stehen</strong><span>mes stovime</span><span>ihr</span><strong>steht</strong><span>jūs stovite</span><span>sie / Sie</span><strong>stehen</strong><span>jie / Jūs stovi</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>singen — dainuoti</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>singe</strong><span>aš dainuoju</span><span>du</span><strong>singst</strong><span>tu dainuoji</span><span>er / sie</span><strong>singt</strong><span>jis / ji dainuoja</span><span>wir</span><strong>singen</strong><span>mes dainuojame</span><span>ihr</span><strong>singt</strong><span>jūs dainuojate</span><span>sie / Sie</span><strong>singen</strong><span>jie / Jūs dainuoja</span></div>\n                  </article>\n                </div>\n                <section class=\"lesson1-block\">\n                  <h4>Pavyzdžiai</h4>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Stehst du?<br>Ja, ich stehe.</div><div class=\"kurss-example\">Steht Albert?<br>Ja, er steht.</div><div class=\"kurss-example\">Steht Marta?<br>Ja, sie steht.</div><div class=\"kurss-example\">Wer kommt und singt?<br>Albert und Marta kommen und singen.</div><div class=\"kurss-example\">Geht ihr?<br>Ja, wir gehen.</div><div class=\"kurss-example\">Wer steht und singt?<br>Albert und Marta stehen und singen.</div></div>\n                </section>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Žodeliai</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info lesson1-vardini-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>Žodžių apytikslis tarimas duotas skliaustuose lietuviškomis raidėmis.<br>To reikia laikytis ir kitose pamokose.</span></div>\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wir (vīr) — mes</div><div class=\"kurss-example\">Vārdā “wir” burts i tiek izrunāts gari.</div><div class=\"kurss-example\">kommen (komen) — ateiti</div><div class=\"kurss-example\">gehen (gē-en) — eiti</div><div class=\"kurss-example\">stehen (štē-en) — stovėti</div><div class=\"kurss-example\">singen (zingen) — dainuoti</div><div class=\"kurss-example\">du (dū) kommst — tu ateini</div><div class=\"kurss-example\">er (ēr) kommt — jis ateina</div><div class=\"kurss-example\">sie (zī) kommt — ji ateina</div><div class=\"kurss-example\">wer (vēr) — kas?</div><div class=\"kurss-example\">ja (jā) — taip</div></div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Tarimas</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Vārdu pareiza izruna, apzīmēta latviešu burtiem, ir dota lekcijās.</div><div class=\"kurss-example\">Wir (vīr) — mes. Žodyje wir ī tariamas visada ilgai.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatika</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>∞</span>Infinityvas</h4><div class=\"lesson1-grammar-note\">Veiksmažodžio pagrindinė forma. Paprastai infinityvas baigiasi -en.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">kommen</div><div class=\"kurss-example\">gehen</div><div class=\"kurss-example\">stehen</div><div class=\"kurss-example\">singen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♟</span>Esamojo laiko galūnės</h4><div class=\"lesson1-ending-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><div class=\"lesson1-ending-info-body\"><p><strong>Nuimk <span class=\"lesson1-ending-accent\">-en</span> nuo veiksmažodžio pagrindinės formos ir pridėk galūnę.</strong></p><p>Pavyzdys: kommen → komm + galūnė</p><div class=\"lesson1-ending-process\" aria-label=\"Esamojo laiko galūnės sudarymo procesas\"><div class=\"lesson1-ending-step\"><strong>kommen</strong><span>pagrindinė forma</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>nuimk <span class=\"lesson1-ending-accent\">-en</span></strong><span>lieka šaknis</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>komm</strong><span>šaknis</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>pridėk galūnę</strong><span>e / st / t</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-results\"><div>komm + <span class=\"lesson1-ending-accent\">e</span> = <strong>komme</strong></div><div>komm + <span class=\"lesson1-ending-accent\">st</span> = <strong>kommst</strong></div><div>komm + <span class=\"lesson1-ending-accent\">t</span> = <strong>kommt</strong></div></div></div></div></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich → -e</div><div class=\"kurss-example\">du → -st</div><div class=\"kurss-example\">er / sie → -t</div><div class=\"kurss-example\">wir → -en</div><div class=\"kurss-example\">ihr → -t</div><div class=\"kurss-example\">sie → -en</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>●</span>Pavyzdžiai</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich komme</div><div class=\"kurss-example\">du kommst</div><div class=\"kurss-example\">er kommt</div><div class=\"kurss-example\">wir kommen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>?</span>Klausiamieji sakiniai</h4><div class=\"lesson1-grammar-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>Vokiečių klausiamajame sakinyje veiksmažodis paprastai perkeliamas į pirmą vietą.</span></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Latviešu valodā:<br>Tu nāc.<br>Vai tu nāc?</div><div class=\"kurss-example\">Vācu valodā:<br>Du kommst.<br>Kommst du?</div><div class=\"kurss-example\">du kommst — tu ateini<br>kommst du? — ar tu ateini?</div><div class=\"kurss-example\">er singt — jis dainuoja<br>singt er? — ar jis dainuoja?</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♣</span>Asmenų skirtumas</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er kommt — jis ateina</div><div class=\"kurss-example\">sie kommt — ji ateina</div><div class=\"kurss-example\">sie kommen — jie / jos ateina</div></div></section>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Išversk</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson1-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"1 pamokos treniruotės kortelė\">\n                    <span class=\"lesson1-training-progress\">1 pamoka · Išversk: 1 / 11</span>\n                    <span class=\"lesson1-training-text\">Ar tu ateini?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Spustelėk kortelę, kad pamatytum vokiečių vertimą. Po atsakymo kitas spustelėjimas parodys kitą kortelę.</p>\n                </div>\n              </div>\n            </details>"
};

